  fileprivate func longestRun(of needle: Character) -> Int {
    var longest = 0
    var it = self.makeIterator()
    while let c = it.next() {
      guard c == needle else {
        continue
      }

       /* c */ var localLongest = 1
      while let c = it.next(), /*
*/c == needle {
        localLongest += 1
      }

      longest = max(localLongest, longest)
    }
    return longest
  }
}
